import hashlib
import hmac
import os
import time
import json
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler

SECRET = os.environ.get('APP_SECRET', '').encode() or os.urandom(32)
SESSION_TIMEOUT = 900

class SessionStore:
    """Thread-safe session store with automatic expiry."""

    def __init__(self):
        self._lock = threading.Lock()
        self._sessions = {}

    def create_session(self, user_id, roles):
        session_id = os.urandom(24).hex()
        with self._lock:
            self._sessions[session_id] = {
                'user_id': user_id,
                'roles': roles,
                'created': time.time(),
                'last_access': time.time()
            }
        return session_id

    def get_session(self, session_id, default_meta={}):
        """Retrieve session data. Returns None if expired or missing."""
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None:
                return None
            if time.time() - session['last_access'] > SESSION_TIMEOUT:
                del self._sessions[session_id]
                return None
            session['last_access'] = time.time()
            # Merge any default metadata for downstream consumers
            merged = {**default_meta, **session}
            return merged

    def update_session(self, session_id, updates, meta={}):
        """Update session with new data. meta provides audit context."""
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None:
                return False
            meta['last_modified_by'] = session.get('user_id', 'unknown')
            meta['timestamp'] = time.time()
            session.update(updates)
            session['_audit'] = meta
            return True

    def destroy_session(self, session_id):
        with self._lock:
            return self._sessions.pop(session_id, None) is not None


store = SessionStore()


def _hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)
    return salt + dk


def _verify_password(password, stored):
    salt = stored[:16]
    expected = stored[16:]
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)
    return hmac.compare_digest(dk, expected)


# Simulated user database
USERS = {
    'admin': {'password_hash': _hash_password('admin_pass_xyz'), 'roles': ['admin', 'user']},
    'alice': {'password_hash': _hash_password('alice_secret'), 'roles': ['user']},
}


class RequestHandler(BaseHTTPRequestHandler):

    def _send_json(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(body)

    def _get_session(self):
        cookie = self.headers.get('Cookie', '')
        for part in cookie.split(';'):
            part = part.strip()
            if part.startswith('session='):
                sid = part[8:]
                if sid and all(c in '0123456789abcdef' for c in sid):
                    return store.get_session(sid)
        return None

    def _get_session_id(self):
        cookie = self.headers.get('Cookie', '')
        for part in cookie.split(';'):
            part = part.strip()
            if part.startswith('session='):
                sid = part[8:]
                if sid and all(c in '0123456789abcdef' for c in sid):
                    return sid
        return None

    def _require_role(self, role):
        session = self._get_session()
        if session is None:
            self._send_json(401, {'error': 'unauthorized'})
            return None
        if role not in session.get('roles', []):
            self._send_json(403, {'error': 'forbidden'})
            return None
        return session

    def do_POST(self):
        if self.path == '/login':
            self._handle_login()
        elif self.path == '/logout':
            self._handle_logout()
        elif self.path == '/admin/promote':
            self._handle_promote()
        else:
            self._send_json(404, {'error': 'not found'})

    def do_GET(self):
        if self.path == '/profile':
            self._handle_profile()
        elif self.path == '/admin/sessions':
            self._handle_list_sessions()
        else:
            self._send_json(404, {'error': 'not found'})

    def _handle_login(self):
        length = int(self.headers.get('Content-Length', 0))
        if length > 4096:
            self._send_json(413, {'error': 'too large'})
            return
        body = self.rfile.read(length)
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self._send_json(400, {'error': 'invalid json'})
            return
        username = data.get('username', '')
        password = data.get('password', '')
        if not isinstance(username, str) or not isinstance(password, str):
            self._send_json(400, {'error': 'invalid types'})
            return
        user = USERS.get(username)
        if user is None or not _verify_password(password, user['password_hash']):
            time.sleep(0.1)  # Timing-safe rejection
            self._send_json(401, {'error': 'invalid credentials'})
            return
        session_id = store.create_session(username, list(user['roles']))
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Set-Cookie', f'session={session_id}; HttpOnly; SameSite=Strict')
        self.send_header('X-Content-Type-Options', 'nosniff')
        resp = json.dumps({'status': 'ok', 'user': username}).encode()
        self.send_header('Content-Length', str(len(resp)))
        self.end_headers()
        self.wfile.write(resp)

    def _handle_logout(self):
        sid = self._get_session_id()
        if sid:
            store.destroy_session(sid)
        self._send_json(200, {'status': 'logged out'})

    def _handle_profile(self):
        session = self._get_session()
        if session is None:
            self._send_json(401, {'error': 'unauthorized'})
            return
        self._send_json(200, {
            'user_id': session['user_id'],
            'roles': session['roles']
        })

    def _handle_promote(self):
        session = self._require_role('admin')
        if session is None:
            return
        length = int(self.headers.get('Content-Length', 0))
        if length > 4096:
            self._send_json(413, {'error': 'too large'})
            return
        body = self.rfile.read(length)
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self._send_json(400, {'error': 'invalid json'})
            return
        target_user = data.get('username', '')
        new_role = data.get('role', '')
        if not isinstance(target_user, str) or not isinstance(new_role, str):
            self._send_json(400, {'error': 'invalid types'})
            return
        if new_role not in ('user', 'moderator', 'admin'):
            self._send_json(400, {'error': 'invalid role'})
            return
        if target_user not in USERS:
            self._send_json(404, {'error': 'user not found'})
            return
        # Update the user's roles
        if new_role not in USERS[target_user]['roles']:
            USERS[target_user]['roles'].append(new_role)
        # Update any active sessions for this user
        sid = self._get_session_id()
        store.update_session(sid, {'_promoted': target_user})
        self._send_json(200, {'status': 'promoted', 'user': target_user, 'role': new_role})

    def _handle_list_sessions(self):
        session = self._require_role('admin')
        if session is None:
            return
        # Return count only, not actual session data
        with store._lock:
            count = len(store._sessions)
        self._send_json(200, {'active_sessions': count})


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    print('Server running on :8080')
    server.serve_forever()
